def post(a, r):
    def cnt(v, upto=N):
        # number of occurrences of v in a[0..upto-1]
        return Sum([If(a[k] == v, 1, 0) for k in range(upto)])

    # M is the number of occurrences of r in the whole array
    M = cnt(r)

    conds = []
    # r must be one of the elements of a
    conds.append(Or([r == a[i] for i in range(N)]))

    for j in range(N):
        w = a[j]
        # r must have maximal count
        conds.append(cnt(w) <= M)
        # tie-break: if w != r has count M, r must reach count M strictly
        # earlier (left to right) than w does
        for p in range(N):
            reached_w_at_p = And(w != r, cnt(w, p + 1) >= M)
            prev = [cnt(r, q + 1) >= M for q in range(p)]
            if prev:
                conds.append(Implies(reached_w_at_p, Or(prev)))
            else:
                conds.append(Not(reached_w_at_p))

    return And(conds)
